  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Acalabrutinib, a pyrrolidine-amide heteroaryl drug, had an absolute oral bioavailability of 25.3% in healthy subjects by IV microtracer, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "AZD0837 showed absolute oral bioavailability of 22–55% in healthy volunteers, a direct human measurement above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide had an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Asciminib had an absolute oral bioavailability of approximately 73% in humans, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Pradigastat had moderate absolute oral bioavailability of ~40% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Maraviroc had 33% oral bioavailability in healthy subjects after a 300 mg dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved high-transfer experimental analogues report absolute oral bioavailability values of 22–90%, with none below 20%; direct human measurements consistently support F ≥ 20%. The query is larger and more peptidic, but there is no affirmative low-F evidence, so the prediction is high with moderate confidence.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "All retrieved analogues are smaller and less peptidic; the query's higher molecular weight and multiple H-bond donors may lower permeability, but no affirmative low-F evidence was retrieved.",
    "Some encainide records show wide interindividual F range (7–82%), indicating first-pass variability, but mean values remain above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

